$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'AKIAIOSFODNN7EXAMPLE:s3cret', '--fault', '"drop;after-bytes=1500000"', 's3://127.0.0.1:8080/' -PassThru -NoNewWindow
